cat > /tmp/candidates.pl <<'PL'
use strict; use warnings;
open my $fh, '<', 'sequences.fasta' or die $!;
my (%s,$n);
while (<$fh>) { chomp; if (/^>(.*)/) { $n=$1; $s{$n}=''; } else { s/\s+//g; $s{$n}.=$_ if defined $n; } }
sub tm { my ($x)=@_; my $v=`oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 $x`; chomp $v; return 0+$v; }
sub rc { my ($x)=@_; $x=reverse $x; $x =~ tr/acgtACGT/tgcaTGCA/; return lc $x; }
my @parts=(
  ['input fwd','input',691,'start'],
  ['input rev','input',210,'end'],
  ['egfp fwd','egfp',4,'start'],
  ['egfp rev','egfp',714,'end'],
  ['flag fwd','flag',7,'start'],
  ['flag rev','flag',87,'end'],
  ['snap fwd','snap',7,'start'],
  ['snap rev','snap',549,'end'],
);
for my $p (@parts) {
  my ($label,$templ,$pos,$side)=@$p;
  print "\n$label\n";
  for my $l (15..36) {
    my $anneal;
    if ($side eq 'start') { $anneal=substr($s{$templ},$pos,$l); }
    else { $anneal=rc(substr($s{$templ},$pos-$l,$l)); }
    my $t=tm($anneal);
    print "$l\t$t\t$anneal\n" if $t>=58 && $t<=72;
  }
}
PL
perl /tmp/candidates.pl

cat > /tmp/validate.pl <<'PL'
use strict; use warnings;
open my $fh, '<', 'sequences.fasta' or die $!;
my (%s,$n);
while (<$fh>) { chomp; if (/^>(.*)/) {$n=$1;$s{$n}=''} else {s/\s+//g;$s{$n}.=$_} }
sub rc {my $x=reverse $_[0];$x =~ tr/acgtACGT/tgcaTGCA/;return lc $x}
sub tm {my $x=shift;chomp(my $v=`oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 $x`);return 0+$v}
my $clamp='gcgc'; my $site='ggtctc'; my $spacer='a';
my @d=(
  {n=>'input', l=>691, e=>210, fl=>20, rl=>33, left=>'taat', right=>'atga', circular=>1},
  {n=>'egfp', l=>4, e=>714, fl=>16, rl=>20, left=>'atga', right=>'ggta'},
  {n=>'flag', l=>7, e=>87, fl=>16, rl=>21, left=>'ggta', right=>'gaca'},
  {n=>'snap', l=>7, e=>546, fl=>19, rl=>16, left=>'gaca', right=>'taat'},
);
my %cores; my %primers;
for my $d (@d) {
  my ($n,$l,$e)=@$d{qw(n l e)};
  my $flen=$d->{fl}; my $rlen=$d->{rl};
  my $fa=substr($s{$n},$l,$flen);
  my $ra=rc(substr($s{$n},$e-$rlen,$rlen));
  my $f=$clamp.$site.$spacer.$d->{left}.$fa;
  my $r=$clamp.$site.rc($spacer).rc($d->{right}).$ra;
  $primers{"${n}_fwd"}=$f; $primers{"${n}_rev"}=$r;
  print ">$n\nF $f\nR $r\nanneal F $fa ",tm($fa)," len ",length($fa),"\nanneal R $ra ",tm($ra)," len ",length($ra)," diff ",abs(tm($fa)-tm($ra)),"\n";
  my $internal='';
  if ($d->{circular}) { $internal=substr($s{$n},$l).substr($s{$n},0,$e); }
  else { $internal=substr($s{$n},$l,$e-$l); }
  # PCR top strand: left tail through anneal + template beyond anneal through endpoint + rc(reverse tail)
  my $top=$clamp.$site.$spacer.$d->{left}.$internal.rc($spacer).rc($d->{right}).rc($site).rc($clamp);
  my $pl=index($top,$site); my $pr=index($top,rc($site));
  die "sites $n $pl $pr" if $pl<0||$pr<0;
  my $cutl=$pl+length($site)+1; my $cutr=$pr-5;
  my $core=substr($top,$cutl,$cutr-$cutl);
  print "core $n ",length($core)," ",substr($core,0,10),"...",substr($core,-10)," expected ";
  my $expected=$d->{circular}?substr($s{$n},$l).substr($s{$n},0,$e):substr($s{$n},$l,$e-$l);
  print length($expected)," ",($core eq $expected?'OK':'BAD'),"\n";
  $cores{$n}=$core;
}
my $assembled=$cores{input}.$cores{egfp}.$cores{flag}.$cores{snap};
print "assembled ",length($assembled)," output ",length($s{output})," ",($assembled eq $s{output}?'MATCH':'MISMATCH'),"\n";
PL
perl /tmp/validate.pl

cat > /tmp/check_primers.pl <<'PL'
use strict; use warnings;
open my $fh,'<','sequences.fasta' or die $!; my (%s,$n); while(<$fh>){chomp;if(/^>(.*)/){$n=$1;$s{$n}=''}else{s/\s+//g;$s{$n}.=$_}}
sub rc{my$x=reverse$_[0];$x=~tr/acgtACGT/tgcaTGCA/;lc$x}
sub tm{my$x=shift;chomp(my$v=`oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 $x`);0+$v}
open my $pf,'<','primers.fasta' or die $!;my(%p,$h);while(<$pf>){chomp;if(/^>(.*)/){$h=$1}else{$p{$h}.=$_}}
my %spec=(input=>[691,210,20,33],egfp=>[4,714,16,20],flag=>[7,87,16,21],snap=>[7,546,19,16]);
my %j=(input=>['taat','atga'],egfp=>['atga','ggta'],flag=>['ggta','gaca'],snap=>['gaca','taat']);
for my $name(qw(input egfp flag snap)){
  my($l,$e,$fl,$rl)=@{$spec{$name}};my($left,$right)=@{$j{$name}};
  for my $dir(qw(fwd rev)){
    my $x=lc$p{"${name}_$dir"}; die "missing $name $dir\n" unless $x;
    die "bad DNA $name $dir\n" unless $x=~/^[acgt]+$/;
    my $ann=substr($x,17);
    my $expected=$dir eq 'fwd'?substr($s{$name},$l,$fl):rc(substr($s{$name},$e-$rl,$rl));
    die "anneal mismatch $name $dir got $ann expected $expected\n" unless $ann eq $expected;
    printf "%s_%s anneal_len=%d Tm=%.3f\n",$name,$dir,length($ann),tm($ann);
    die "Tm range $name $dir\n" unless length($ann)>=15&&length($ann)<=45&&tm($ann)>=58&&tm($ann)<=72;
    die "BsaI absent $name $dir\n" unless substr($x,6,6) eq 'ggtctc';
  }
  my $d=abs(tm(substr(lc$p{"${name}_fwd"},17))-tm(substr(lc$p{"${name}_rev"},17)));
  printf "%s pair_delta=%.3f\n",$name,$d; die "pair delta\n" if $d>5;
}
# Source sequences have no internal BsaI sites; count each designed amplicon orientation site.
for my $name(keys %s){for my $site(qw(g g)){}}
print "all primer constraints passed\n";
PL
